CREATE DATABASE IF NOT EXISTS mashrafi_tools CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mashrafi_tools;
CREATE TABLE IF NOT EXISTS calc_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,expression_text VARCHAR(500) NOT NULL,result_text VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gantt_tasks(id BIGINT PRIMARY KEY AUTO_INCREMENT,day_no INT NOT NULL,title VARCHAR(255) NOT NULL,task_date DATE NOT NULL,description VARCHAR(1000),progress INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
SHOW TABLES;